/// A node's child slots: the bit positions of its `Children` mask, and the `order`
/// argument to `Ast.childAtOrder`.
///
/// Slots are declared per node type rather than per kind because that is how the schema
/// declares them, and a node type is what you have in hand when you write the call.
[<RequireQualifiedAccess>]
module internal Slot =

    /// Slots of `SyntaxKind.QualifiedName`.
    [<RequireQualifiedAccess>]
    module QualifiedName =

        /// Slot 0.
        [<Literal>]
        let Left = 0<astSlot>

        /// Slot 1.
        [<Literal>]
        let Right = 1<astSlot>

        /// The slot names in slot order, matching the encoder's `childProperties`.
        let Names = [| "left"; "right" |]

    /// Slots of `SyntaxKind.ComputedPropertyName`.
    [<RequireQualifiedAccess>]
    module ComputedPropertyName =

        /// Slot 0.
        [<Literal>]
        let Expression = 0<astSlot>

        /// The slot names in slot order, matching the encoder's `childProperties`.
        let Names = [| "expression" |]

    /// Slots of `SyntaxKind.Decorator`.
    [<RequireQualifiedAccess>]
    module Decorator =

        /// Slot 0.
        [<Literal>]
        let Expression = 0<astSlot>

        /// The slot names in slot order, matching the encoder's `childProperties`.
        let Names = [| "expression" |]

    /// Slots of `SyntaxKind.IfStatement`.
    [<RequireQualifiedAccess>]
    module IfStatement =

        /// Slot 0.
        [<Literal>]
        let Expression = 0<astSlot>

        /// Slot 1.
        [<Literal>]
        let ThenStatement = 1<astSlot>

        /// Slot 2. Optional.
        [<Literal>]
        let ElseStatement = 2<astSlot>

        /// The slot names in slot order, matching the encoder's `childProperties`.
        let Names = [| "expression"; "thenStatement"; "elseStatement" |]

    /// Slots of `SyntaxKind.DoStatement`.
    [<RequireQualifiedAccess>]
    module DoStatement =

        /// Slot 0.
        [<Literal>]
        let Statement = 0<astSlot>

        /// Slot 1.
        [<Literal>]
        let Expression = 1<astSlot>

        /// The slot names in slot order, matching the encoder's `childProperties`.
        let Names = [| "statement"; "expression" |]

    /// Slots of `SyntaxKind.WhileStatement`.
    [<RequireQualifiedAccess>]
    module WhileStatement =

        /// Slot 0.
        [<Literal>]
        let Expression = 0<astSlot>

        /// Slot 1.
        [<Literal>]
        let Statement = 1<astSlot>

        /// The slot names in slot order, matching the encoder's `childProperties`.
        let Names = [| "expression"; "statement" |]

    /// Slots of `SyntaxKind.ForStatement`.
    [<RequireQualifiedAccess>]
    module ForStatement =

        /// Slot 0. Optional.
        [<Literal>]
        let Initializer = 0<astSlot>

        /// Slot 1. Optional.
        [<Literal>]
        let Condition = 1<astSlot>

        /// Slot 2. Optional.
        [<Literal>]
        let Incrementor = 2<astSlot>

        /// Slot 3.
        [<Literal>]
        let Statement = 3<astSlot>

        /// The slot names in slot order, matching the encoder's `childProperties`.
        let Names = [| "initializer"; "condition"; "incrementor"; "statement" |]

    /// Slots of `ForInOrOfStatement`, which is 2 kinds (`ForInStatement` and others).
    [<RequireQualifiedAccess>]
    module ForInOrOfStatement =

        /// Slot 0. Optional.
        [<Literal>]
        let AwaitModifier = 0<astSlot>

        /// Slot 1.
        [<Literal>]
        let Initializer = 1<astSlot>

        /// Slot 2.
        [<Literal>]
        let Expression = 2<astSlot>

        /// Slot 3.
        [<Literal>]
        let Statement = 3<astSlot>

        /// The slot names in slot order, matching the encoder's `childProperties`.
        let Names = [| "awaitModifier"; "initializer"; "expression"; "statement" |]

    /// Slots of `SyntaxKind.BreakStatement`.
    [<RequireQualifiedAccess>]
    module BreakStatement =

        /// Slot 0. Optional.
        [<Literal>]
