/// Byte offsets into the `SourceFile` node's extended-data record.
///
/// Unlike everything else here, this layout is not in `ast.json`. The record is written by
/// a hand-written Go function and read by hand-written TypeScript, so the only statement of
/// its shape is the format documentation in `encoder.go`, which the generator parses. Every
/// field is a `uint32`; `Ast` in `Library.fs` is what gives them meaning.
[<RequireQualifiedAccess>]
module SourceFileRecord =

    /// The record's total size in bytes.
    [<Literal>]
    let Size = 76

    /// The value a structured-data offset or string index carries when the field is absent.
    [<Literal>]
    let Absent = 0xFFFFFFFFu

    /// Index of `text` in the string offsets section.
    [<Literal>]
    let Text = 0<byteOffset>

    /// Index of `fileName` in the string offsets section.
    [<Literal>]
    let FileName = 4<byteOffset>

    /// Index of `path` in the string offsets section.
    [<Literal>]
    let Path = 8<byteOffset>

    /// Value of `languageVariant`.
    [<Literal>]
    let LanguageVariant = 12<byteOffset>

    /// Value of `scriptKind`.
    [<Literal>]
    let ScriptKind = 16<byteOffset>

    /// Byte offset of `referencedFiles` in structured data section.
    [<Literal>]
    let ReferencedFiles = 20<byteOffset>

    /// Byte offset of `typeReferenceDirectives` in structured data.
    [<Literal>]
    let TypeReferenceDirectives = 24<byteOffset>

    /// Byte offset of `libReferenceDirectives` in structured data.
    [<Literal>]
    let LibReferenceDirectives = 28<byteOffset>

    /// Byte offset of `imports` node index array in structured data.
    [<Literal>]
    let Imports = 32<byteOffset>

    /// Byte offset of `moduleAugmentations` node index array.
    [<Literal>]
    let ModuleAugmentations = 36<byteOffset>

    /// Byte offset of `ambientModuleNames` string array.
    [<Literal>]
    let AmbientModuleNames = 40<byteOffset>

    /// Node index of `externalModuleIndicator` (0 = nil).
    [<Literal>]
    let ExternalModuleIndicator = 44<byteOffset>

    /// Index of `originalText` in the string offsets section.
    [<Literal>]
    let OriginalText = 48<byteOffset>

    /// Byte offset of `spanMap` in structured data.
    [<Literal>]
    let SpanMap = 52<byteOffset>

    /// Byte offset of `supplementalSourceFileNames` in structured data.
    [<Literal>]
    let SupplementalSourceFileNames = 56<byteOffset>

    /// Index of `canonicalSourceFileName`, or noStructuredData.
    [<Literal>]
    let CanonicalSourceFileName = 60<byteOffset>

    /// Index of `contentMapper`, or noStructuredData.
    [<Literal>]
    let ContentMapper = 64<byteOffset>

    /// Index of `virtualFileName`, or noStructuredData.
    [<Literal>]
    let VirtualFileName = 68<byteOffset>

    /// Byte offset of `diagnosticDirectives` in structured data.
    [<Literal>]
    let DiagnosticDirectives = 72<byteOffset>
